INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch11$PT156-S4-Q23$batch11$, 156, 4, 23, $batch11$Flaw$batch11$, $batch11$The computer software industry is rapidly growing and has been for some time. For a company to grow rapidly, it must be innovative, which means it must have creative employees or a management that is open to new ideas. Logichut is a software company that is said to have no creative employees. If so, its management is evidently open to new ideas.$batch11$, $batch11$The reasoning in the argument is flawed in that it$batch11$, $batch11$A$batch11$, true, $batch11$Batch 11; question text from local bank.$batch11$ FROM lr_sections s WHERE s.preptest=156 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT156-S4-Q23$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$A$batch11$, $batch11$illicitly presumes that because a set of things has a certain property, each member of that set has the property$batch11$, $batch11$Correct$batch11$, true FROM lr_questions q WHERE q.qid=$batch11$PT156-S4-Q23$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$A$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$B$batch11$, $batch11$confuses a necessary condition for a company’s being innovative with a sufficient condition for a company’s being innovative$batch11$, $batch11$Not the flaw$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S4-Q23$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$B$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$C$batch11$, $batch11$illicitly concludes that because many people believe something, it must be true$batch11$, $batch11$Not the flaw$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S4-Q23$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$C$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$D$batch11$, $batch11$confuses a necessary condition for a company to grow rapidly with a sufficient condition for a company to grow rapidly$batch11$, $batch11$Not the flaw$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S4-Q23$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$D$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$E$batch11$, $batch11$overlooks the possibility that a software company could have both creative employees and a management that is open to new ideas$batch11$, $batch11$Not the flaw$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S4-Q23$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$E$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT156-S4-Q23$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Conclusion$batch11$, $batch11$If Logichut has no creative employees, its management must be open to new ideas.$batch11$), (1, $batch11$Evidence$batch11$, $batch11$The software industry is growing rapidly. Rapid company growth → innovation → creative employees or open management. Logichut is a software company.$batch11$), (2, $batch11$Evaluate$batch11$, $batch11$The rule applies to a company growing rapidly. The industry is growing, but that doesn't mean every company in it is. The argument moves from a property of the whole industry to Logichut. That's a whole-to-part flaw.$batch11$), (3, $batch11$Goal$batch11$, $batch11$The argument assumes each company in a growing industry is itself growing.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT156-S4-Q23$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$The industry is growing, so the argument treats Logichut as growing. A whole's property doesn't pass to each part.$batch11$), ($batch11$B$batch11$, $batch11$The argument uses innovation correctly as requiring creative employees or open management.$batch11$), ($batch11$C$batch11$, $batch11$"Said to have" is only a premise for the "if so" conditional. The argument doesn't conclude it's true.$batch11$), ($batch11$D$batch11$, $batch11$Growth is used correctly as requiring innovation. The problem is assuming Logichut grows at all.$batch11$), ($batch11$E$batch11$, $batch11$The argument allows both. It only says management must be open if there are no creative employees.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT156-S4-Q23$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
